  "mode.gunluk": "Günlük",
  "tut.fusion": "Füzyon açıldı! Birbirine yakın iki 3. seviye element kulesi (Ejder Ocağı, Ayaz, Fırtına, Simyacı) birleşebilir. Birine dokun, menüde ortağının birleşik resmini seç: iki kule tek ve çok daha güçlü bir kuleye dönüşür.",
  "branch.fz_buhar": "Buhar Kazanı",
  "branch.fz_buhar.desc": "Ateş ve buz birleşti: yanan alev topu düştüğü yerde yavaşlatan bir buhar bulutu bırakır.",
  "branch.fz_simsek": "Ateş Fırtınası",
  "branch.fz_simsek.desc": "Kızıl şimşek düşmandan düşmana sıçrar ve vurduğu her şeyi tutuşturur.",
  "branch.fz_duman": "Zehirli Duman",
  "branch.fz_duman.desc": "Zehir iksiri alevle tutuşur: her atış zehirler, yakar ve patlatır.",
  "branch.fz_kutup": "Kutup Kulesi",
  "branch.fz_kutup.desc": "Buz mavisi şimşek yavaşlatır; her üç atışta bir ilk hedefi dondurur.",
  "branch.fz_curuk": "Çürük Buz",
  "branch.fz_curuk.desc": "Donmuş zehir zırhı çürütür, düşmanları yavaşlatır ve uzun süre zehirler.",
  "branch.fz_asit": "Asit Fırtınası",
  "branch.fz_asit.desc": "Asit yağmuru ıslatır ve zehirler; ardından yeşil şimşek zehirlilerin arasında sıçrar.",
  "branch.fz_buhar2": "Büyük Buhar Kazanı",
  "branch.fz_buhar2.desc": "Daha geniş ateş, daha yoğun buhar, daha uzun yavaşlatma.",
  "branch.fz_simsek2": "Cehennem Fırtınası",
  "branch.fz_simsek2.desc": "Şimşek yedi düşmana sıçrar, alevleri daha da harlıdır.",
  "branch.fz_duman2": "Kara Duman",
  "branch.fz_duman2.desc": "Daha geniş alan, daha ağır zehir.",
  "branch.fz_kutup2": "Ebedi Kış",
  "branch.fz_kutup2.desc": "Altı düşmana sıçrar, daha uzun dondurur.",
  "branch.fz_curuk2": "Kara Buz",
  "branch.fz_curuk2.desc": "Zırhı daha uzun süre çürütür, zehri ağırlaştırır.",
  "branch.fz_asit2": "Asit Tufanı",
  "branch.fz_asit2.desc": "Şimşek altı zehirli düşmana sıçrar.",
