  "mode.kahramanca.d": "Düşmanların canı %50, hızı %10 fazla.",
  "mode.demir.d": "Kalenin tek canı var; düşman canı %25 fazla.",
  "mode.locked": "Bölümü bir kez kazanınca açılır",
  "mode.badge": "{m} rozeti",
  "end.levelUp": "Seviye {n}!",
  "hero.levelShort": "Seviye {n}",
  "reward.treasure": "{n} Krallık Hazinesi",
  "reward.mastery": "{n} Kule ustalık parçası",
  "reward.diamonds": "{n} Elmas",
  "reward.heroShard": "Kahraman parçası",
  "reward.banner": "Kozmetik bayrak",
  "speaker.scout": "İzci",
  "speaker.villager": "Değirmenci",
  "vaka.1": "Karakolda Şafak",
  "vaka.1.metin": "Sınır karakolunda sabah sisi dağılmadan orman ateş gözleriyle doldu. Goblinler ilk kez bu kadar düzenli yürüyordu. O gün ilk kuleler kuruldu, ilk oklar atıldı. Ölen şefin boynundaki kuzgun tüyünü kimse önemsemedi. Önemsemeliydiler.",
  "vaka.2": "Değirmen Yanarken",
  "vaka.2.metin": "Kurtlar gece geldi. Değirmen alev alev yanarken köylüler kaleye koştu. Sarya o gece kimseye söylemedi ama yıllar önce kendi köyü de böyle yanmıştı ve kimse gelmemişti. Bu sefer gelen vardı. Sabah olduğunda herkes aynı soruyu soruyordu: kurtları köye kim sürdü?",
  "vaka.3": "Kuzgunların Geçidi",
  "vaka.3.metin": "Akınlar aynı saatte, aynı yoldan geliyordu. Geçit tutuldu, ateşle buz buluşunca sis yükseldi. Haydut yüzbaşısı son nefesinde iki kelime fısıldadı: 'Tacı düşürün.' O gün kimse anlamadı. Thorgar ise haydutların çeliğine uzun uzun baktı.",
  "vaka.4": "Taş Köprü",
  "vaka.4.metin": "Taş Köprü'de eski bir balista ve iki terk edilmiş maden bulundu. Zırhlı haydutlar köprüye yığıldı ama geçemediler. Bir kalkanın arkasında kazınmış bir armanın gölgesi kaldı: bir pençe. Aldric onu tanıdı ve tanımamış gibi yaptı.",
  "vaka.5": "Fırtına Tepesi",
  "vaka.5.metin": "Fırtına Tepesi'nin kulesi yüzyıllar sonra uyandı; şimşek düşmandan düşmana sıçradı. Gökyüzünü karartan kuzgunların gözlerinde rünler parlıyordu. Velmora o büyüyü tanıdı ve ilk kez bir soruya cevap vermedi.",
  "vaka.6": "Sisli Bataklık",
  "vaka.6.metin": "Sisli bataklıkta şamanlar ölüleri büyüyle ayakta tutuyordu. Dağın kartalları gökyüzünü temizledi. Şamanın çantasından çıkan mektubun mühründe kırmızı bir pençe vardı ve tek bir satır: 'Kapıyı aç. Gerisini taç halleder.' Aldric mührü tanıdı: Garrik Redclaw, bir zamanlar canını kurtaran adam.",
  "vaka.7": "Yağmacı Kampı",
  "vaka.7.metin": "Garrik'in yağmacı kampı kazık duvarların ardında kaynıyordu. Garrik eski dostuna burçlardan seslendi: 'Bir gün seni de sürgüne yollayacaklar.' Simyacının iksirleri zırhları eritti, ateşle buluşan zehir patladı. Kamp düştü ama Garrik kalesine çekildi.",
  "vaka.8": "Redclaw'ın Kalesi",
  "vaka.8.metin": "İki eski dost, Redclaw'ın kapısında karşılaştı. Garrik düşerken güldü: 'Ben sadece kapıyı açtım. Asıl gelen Varhol'dan. Tacına iyi bak.' O gece Velmora konseye ilk kez korkuyla baktı. Bundan sonrası çok daha eski bir hikâyeydi.",
  "vaka.9": "Kül Yağmuru",
  "vaka.9.metin": "Tarlalara kül yağıyordu ama ortada yangın yoktu. Kül Varhol'dan geliyordu ve içinde ölü büyüsü vardı. İskeletler yıkıldıkça yeniden kalktı; yalnızca ateşle düşenler toprakta kaldı. Velmora savaş biter bitmez fısıldadı: 'Bu kadar ustasını ancak ben yetiştirdim.'",
  "vaka.10": "Taş Bekçiler",
  "vaka.10.metin": "Eski mabedin heykelleri kaidelerinden kalkıp gökyüzüne yükseldi. Savaştan sonra her kaidede aynı mühür vardı: mor bir kafatası. Velmora sonunda anlattı: Iskar onun öğrencisiydi; ölüleri dinlemeyi ona o öğretmiş, sürgüne de o göndertmişti.",
  "vaka.11": "Fısıltılar Mezarlığı",
  "vaka.11.metin": "Fısıltılar Mezarlığı'nda öğrenci hocasını bekliyordu. Iskar geri çekilirken sırrı ortaya döktü: Kemik Kral'ın mezarını kapatan mühür bir taş değil, krallığın tacıydı. Taç düşerse mühür kırılacaktı. İlk hedefi de belliydi: Aldric'in evi, Kuzey Kalesi.",
  "vaka.12": "Kuzey Kalesi'nin Düşüşü",
  "vaka.12.metin": "Kuzey Kalesi'nin duvarlarını Aldric'in dedesi dikmişti. O gün Aldric kaleyi kurtaramayacağını biliyordu ama halkı kurtarabilirdi. Son köylü kapıdan çıktığında sancağını indirdi, ama yere düşürmedi. 'Geri döneceğiz,' dedi.",
  "vaka.13": "Koç ve Kalkan",
  "vaka.13.metin": "Thorgar ocağını vadiye kurdu ve gece gündüz çekiç salladı. Şafakta kalkanlar hazırdı. O zaman konseye atalarından kalan sırrı anlattı: tacı onlar dövmüştü, Kemik Kral'ın mezar mührünü eriterek. Taç taşındıkça mühür tutacaktı.",
  "vaka.14": "Element Mabedi",
  "vaka.14.metin": "Element Mabedi'nde dört güç uyuyordu ama Velmora yalnızca birini uyandırabildi. Seçim savaşın kaderini belirledi. Üç yoldan gelen ölüler rün çemberinde dağıldı ve tacın mührü yeniden sıkılaştı. Kuzey Kalesi'ni geri almanın zamanı gelmişti.",
  "vaka.15": "Kuzey Kalesi'ni Geri Al",
  "vaka.15.metin": "Şafakta saldırdılar. Kemik devleri yıkıldıkça içlerinden iskeletler döküldü ama yeni kalkanlar geri adım attırmadı. Öğleye doğru ölü sancakları indi ve Aldric dedesinin burçlarına kendi sancağını çekti. Iskar ise çoktan Kemik Taht'a kaçmıştı.",
  "vaka.16": "Kemik Taht",
  "vaka.16.metin": "Kemik Kral yüzyıllık uykusundan uyandı ve atalardan kalma borcu istedi. Dört kahraman geri çekilmedi; sonunda taht yıkıldı, ölüler toprağa döndü ve mühür tuttu. Yalnızca iki şey eksikti: Iskar ve asası. Bir çağ kapandı. Hikâye bitmedi.",
