  "branch.guards.desc": "3 armored knights: very high health and 50% armor. Holds the road for a long time.",
  "branch.berserkers": "Berserkers",
  "branch.berserkers.desc": "3 furious fighters: high damage, fast strikes, quick respawn.",
  "branch.hellCatapult": "Hell Catapult",
  "branch.hellCatapult.desc": "Very long range, huge fireballs: wide area damage and strong burning.",
  "branch.flameBreath": "Flame Breath",
  "branch.flameBreath.desc": "A constant short-range stream of fire that burns everyone in front of it.",
  "branch.iceSeal": "Ice Seal",
  "branch.iceSeal.desc": "The 4th hit on the same enemy freezes it for 2 s (bosses briefly). Strong slow.",
  "branch.blizzard": "Blizzard",
  "branch.blizzard.desc": "Every shot slows and damages all enemies in a wide area.",
  "branch.piercingSpear": "Piercing Spear",
  "branch.piercingSpear.desc": "The spear pierces its target and the enemies behind it. Ignores most armor.",
  "branch.hook": "Hook",
  "branch.hook.desc": "Drags the target back along the road and stuns it briefly. Bosses are not pulled.",
  "branch.mint": "Mint",
  "branch.mint.desc": "42 gold every 8 s while a wave runs. Multiplies your economy.",
  "branch.treasureGuard": "Treasure Guard",
  "branch.treasureGuard.desc": "28 gold income, plus a guard who shoots nearby enemies.",
  "branch.chainLightning": "Chain Lightning",
  "branch.chainLightning.desc": "Lightning jumps between up to 7 enemies over long distances.",
  "branch.thunder": "Thunderclap",
  "branch.thunder.desc": "A huge bolt from the sky: heavy damage, half damage around it, and a stun.",
  "branch.griffinRiders": "Griffin Riders",
  "branch.griffinRiders.desc": "Griffin riders strike both air and ground. High damage.",
  "branch.eagleFlock": "Eagle Flock",
  "branch.eagleFlock.desc": "Each volley hits 3 different flying enemies at once.",
  "branch.plague": "Plague",
  "branch.plague.desc": "A wide plague cloud: very strong, long-lasting poison.",
  "branch.acid": "Acid",
  "branch.acid.desc": "High impact damage; halves armor for 7 s.",
