  "tut.skip": "Skip tutorial",
  "tut.1": "Goblins are out of the forest and marching on the castle! Tap one of the glowing stone rings; we will raise a tower there.",
  "tut.2": "Choose the Watch Tower and confirm. Its archers rain arrows on anything in range.",
  "tut.3": "That's it! Now build a Barracks right by the road. My soldiers hold the enemy on the road while the towers strike.",
  "tut.4": "Tap the barracks and press the flag icon to choose where the soldiers stand.",
  "tut.5": "When you are ready, sound the horn: start the wave. Every fallen enemy brings gold to the treasury.",
  "tut.hero":
    "This is your commander, {name}. Tap them, then tap where they should go. They will meet enemies on the road.",
