  "reach.vlong": "Very long",
  "strip.armor": "Armor",
  "tut.6": "As gold piles up, tap towers to upgrade them. And don't forget your hero: tap them, then tap where they should go.",
  "tut.burn": "The Dragon Forge throws fire. Burning enemies take damage every second for a while.",
  "tut.combo":
    "Elements trigger each other. When ice strikes a burning enemy, the rising steam slows everything inside it. Build a Dragon Forge next to a Frost Tower.",
  "tut.spell": "Your hero’s first spell is ready. Tap it at the bottom left, then tap the target.",
