  "tut.fusion": "Fusion unlocked! Two nearby level-3 elemental towers (Dragon Forge, Frost, Storm, Alchemist) can merge. Tap one and pick its partner's fused image in the menu: the two towers become a single, far stronger one.",
  "branch.fz_buhar": "Steam Cauldron",
  "branch.fz_buhar.desc": "Fire and ice combined: the burning fireball leaves a slowing steam cloud where it lands.",
  "branch.fz_simsek": "Firestorm",
  "branch.fz_simsek.desc": "Crimson lightning leaps from foe to foe and sets everything it strikes ablaze.",
  "branch.fz_duman": "Toxic Smoke",
  "branch.fz_duman.desc": "The poison potion ignites: every shot poisons, burns and explodes.",
  "branch.fz_kutup": "Polar Spire",
  "branch.fz_kutup.desc": "Ice-blue lightning slows; every third shot freezes the first target.",
  "branch.fz_curuk": "Rotting Ice",
  "branch.fz_curuk.desc": "Frozen poison rots armor, slows enemies and poisons them for a long time.",
  "branch.fz_asit": "Acid Storm",
  "branch.fz_asit.desc": "Acid rain soaks and poisons, then green lightning leaps between the poisoned.",
  "branch.fz_buhar2": "Great Steam Cauldron",
  "branch.fz_buhar2.desc": "Wider fire, thicker steam, longer slow.",
  "branch.fz_simsek2": "Hellstorm",
  "branch.fz_simsek2.desc": "Lightning leaps to seven foes, flames burn hotter.",
  "branch.fz_duman2": "Black Smoke",
  "branch.fz_duman2.desc": "Wider area, heavier poison.",
  "branch.fz_kutup2": "Eternal Winter",
  "branch.fz_kutup2.desc": "Leaps to six foes, freezes longer.",
  "branch.fz_curuk2": "Black Ice",
  "branch.fz_curuk2.desc": "Rots armor longer, poison grows heavier.",
  "branch.fz_asit2": "Acid Deluge",
  "branch.fz_asit2.desc": "Lightning leaps between six poisoned foes.",
  "hud.fusion": "Fusion",
