  "vaka.1": "Dawn at the Outpost",
  "vaka.1.metin": "Before the morning mist had lifted, the forest by the border outpost filled with burning eyes. Never before had goblins marched in such order. That day the first towers rose and the first arrows flew. No one paid attention to the raven feather around the dead chief's neck. They should have.",
  "vaka.2": "While the Mill Burned",
  "vaka.2.metin": "The wolves came by night. As the mill burned, the villagers ran for the castle. Sarya told no one, but years ago her own village had burned like this, and no one had come. This time someone did. By morning everyone was asking the same question: who drove the wolves to the village?",
  "vaka.3": "Pass of Ravens",
  "vaka.3.metin": "The raids came at the same hour, down the same road. The pass held; where fire met frost, mist rose. With his last breath the bandit captain whispered three words: 'Bring down the crown.' No one understood that day. Thorgar, though, stared long at the bandits' steel.",
  "vaka.4": "The Stone Bridge",
  "vaka.4.metin": "At the Stone Bridge an old ballista and two abandoned mines were found. Armored bandits crowded the bridge but could not cross. On the back of a shield, the ghost of a scraped crest remained: a claw. Aldric recognized it, and pretended he did not.",
  "vaka.5": "Storm Hill",
  "vaka.5.metin": "After centuries, the tower on Storm Hill woke; lightning leapt from foe to foe. Runes glowed in the eyes of the ravens that darkened the sky. Velmora recognized the spell, and for the first time, left a question unanswered.",
  "vaka.6": "The Misty Swamp",
  "vaka.6.metin": "In the misty swamp, shamans kept the fallen standing with sorcery. The mountain eagles cleared the sky. The letter in the shaman's satchel bore a red claw seal and a single line: 'Open the gate. The crown will do the rest.' Aldric knew the seal: Garrik Redclaw, the man who once saved his life.",
  "vaka.7": "The Raider Camp",
  "vaka.7.metin": "Garrik's raider camp seethed behind its palisade. From the ramparts, Garrik called to his old friend: 'One day they will exile you too.' The alchemist's brews melted armor; poison met fire and exploded. The camp fell, but Garrik withdrew to his castle.",
  "vaka.8": "Redclaw's Fortress",
  "vaka.8.metin": "Two old friends met at Redclaw's gate. As Garrik fell, he laughed: 'I only opened the gate. The real enemy comes from Varhol. Guard your crown.' That night Velmora looked at the council with fear for the first time. What came next was a far older story.",
  "vaka.9": "Ash Rain",
  "vaka.9.metin": "Ash fell on the fields, though nothing burned. It drifted from Varhol, heavy with necromancy. Skeletons rose again each time they fell; only those that fell burning stayed down. When the battle ended, Velmora whispered: 'A master this skilled, only I could have trained.'",
  "vaka.10": "The Stone Sentinels",
  "vaka.10.metin": "The statues of the old temple rose from their pedestals into the sky. After the battle, every pedestal bore the same seal: a purple skull. At last Velmora told them: Iskar had been her apprentice; she had taught him to listen to the dead, and she had him exiled.",
  "vaka.11": "Graveyard of Whispers",
  "vaka.11.metin": "In the Graveyard of Whispers, the apprentice awaited his master. As Iskar withdrew, he laid the secret bare: the seal on the Bone King's tomb was not a stone but the kingdom's crown. If the crown fell, the seal would break. His first target was clear: Aldric's home, the North Keep.",
  "vaka.12": "Fall of the North Keep",
  "vaka.12.metin": "Aldric's grandfather had raised the walls of the North Keep. That day Aldric knew he could not save the keep, but he could save its people. When the last villager passed the gate, he lowered his banner, but did not let it fall. 'We will return,' he said.",
  "vaka.13": "Ram and Shield",
  "vaka.13.metin": "Thorgar set his forge in the valley and swung his hammer day and night. By dawn the shields were ready. Then he told the council his ancestors' secret: they had forged the crown, by melting down the Bone King's tomb seal. As long as the crown was worn, the seal would hold.",
  "vaka.14": "Temple of Elements",
  "vaka.14.metin": "Four powers slept in the Elemental Temple, but Velmora could wake only one. The choice decided the battle. The dead marching down three roads broke against the rune circle, and the crown's seal tightened once more. It was time to take back the North Keep.",
  "vaka.15": "Retake the North Keep",
  "vaka.15.metin": "They attacked at dawn. As bone giants crumbled, skeletons poured out of them, but the new shields did not give a step. By noon the dead banners came down, and Aldric raised his own on his grandfather's battlements. Iskar had long since fled to the Bone Throne.",
  "vaka.16": "The Bone Throne",
  "vaka.16.metin": "The Bone King woke from his centuries of sleep and demanded the ancestral debt. The four heroes did not retreat; at last the throne shattered, the dead returned to the earth, and the seal held. Only two things were missing: Iskar, and his staff. An age had ended. The story had not.",
