var SONSUZ_BOSS = ["goblinChief", "alphaWolf", "banditCaptain", "garrik", "iskar", "kemikKral"];
function sonsuzDalgalar(n = 150) {
  // görülmüş düşmanlardan karışık dalgalar; her 5. dalgada boss, giderek kalabalık ve sık
  let gor = new Set(P().seenEnemies ?? []),
    havuz = SONSUZ_HAVUZ.filter(([e]) => e === "goblin" || e === "wolf" || gor.has(e)),
    bosslar = SONSUZ_BOSS.filter((e) => e === "goblinChief" || gor.has(e)),
    r = (k) => Math.floor(Math.random() * k),
    out = [];
  for (let w = 1; w <= n; w++) {
    let uygun = havuz.filter(([, d]) => d <= w + 2).map(([e]) => e),
      gk = Math.min(4, 2 + Math.floor(w / 7)),
      groups = [],
      yogun = 1 + w * 0.09;
    for (let g = 0; g < gk; g++) {
      let e = uygun[uygun.length - 1 - r(Math.min(uygun.length, 5))],
        agir = ["armoredBandit", "swampSlime", "iceTroll", "runeGuard", "varholKnight", "ram", "boneGiant", "gargoyle"].includes(e),
        c = Math.round((agir ? 2 : 7) * yogun * (0.8 + Math.random() * 0.5));
      groups.push({ enemy: e, count: Math.max(1, c), interval: Math.max(0.35, (agir ? 2 : 0.8) - w * 0.012), delay: g * 6, elite: w > 6 && Math.random() < 0.35 ? 1 + r(2) : 0 });
    }
    if (w % 5 === 0) groups.push({ enemy: bosslar[(w / 5 - 1) % bosslar.length], count: 1, interval: 1, delay: 8 });
    out.push({ groups });
  }
  return out;
}
